head.script:
scwin.focusHandler2 = function() {
    window.focusedInput = this.id;
}
scwin.__isBackground = function() {
    var color = WebSquare.wUnit.getJq("#wframe1_input2").css("background-color");
    if (color.indexOf("rgb") < 0) {
        return color == "#ff6666";
    }
    return color == "rgb(255, 102, 102)";
}
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#input3', 'key-combo', {
        combo: 'TAB'
    });
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('input3').focus()");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. 보라색영역의 wframe1_input2로 포커스가 이동되어진다.
    //2. The focus is shifted to wframe1_input2 in the violet area.
    WebSquare.wUnit.addCommand("assert", "scwin.__isBackground()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    input1.setValue(input1.id);
    input2.setValue(input2.id);
    input3.setValue(input3.id);
    input4.setValue(input4.id);
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 16-Mar-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
